  corrModeratePos: { ja: "中程度の正の相関があります。", en: "There is a moderate positive correlation.", zh: "存在中等程度的正相关。", it: "C'è una correlazione positiva moderata.", de: "Es besteht eine moderate positive Korrelation.", fr: "Il existe une corrélation positive modérée.", es: "Hay una correlación positiva moderada.", ko: "중간 정도의 양의 상관관계가 있습니다." },
  corrModerateNeg: { ja: "中程度の負の相関があります。", en: "There is a moderate negative correlation.", zh: "存在中等程度的负相关。", it: "C'è una correlazione negativa moderata.", de: "Es besteht eine moderate negative Korrelation.", fr: "Il existe une corrélation négative modérée.", es: "Hay una correlación negativa moderada.", ko: "중간 정도의 음의 상관관계가 있습니다." },
  corrWeakPos: { ja: "弱い正の相関があります。", en: "There is a weak positive correlation.", zh: "存在较弱的正相关。", it: "C'è una debole correlazione positiva.", de: "Es besteht eine schwache positive Korrelation.", fr: "Il existe une faible corrélation positive.", es: "Hay una correlación positiva débil.", ko: "약한 양의 상관관계가 있습니다." },
  corrWeakNeg: { ja: "弱い負の相関があります。", en: "There is a weak negative correlation.", zh: "存在较弱的负相关。", it: "C'è una debole correlazione negativa.", de: "Es besteht eine schwache negative Korrelation.", fr: "Il existe une faible corrélation négative.", es: "Hay una correlación negativa débil.", ko: "약한 음의 상관관계가 있습니다." },
